-- 036: version 19, food extras (engineer X2).
--
--  1. Vitamins and minerals on a food (FOOD-17): one `micros` object per
--     food, keyed by a short code ('vd' vitamin D, 'fe' iron …, the list is
--     src/lib/micros-rules.ts), per 100 g or 100 ml, in the unit of
--     Regulation (EU) No 1169/2011 Annex XIII part A, which is also NEVO's
--     unit. One jsonb column rather than 27 numeric ones: most foods carry
--     20 figures or none, a person's own food a handful from its label, and
--     every reader (the food page, the day, recipes, the stats) reads them
--     as one set the person picks from; a column a nutrient would widen
--     every row the app syncs and every select, and a 28th nutrient would
--     need another migration. The figures are checked here all the same
--     (known codes only, numbers from 0 to 1,000,000).
--  2. The shared catalogue's vitamins and minerals from NEVO-online
--     2025/9.0, unchanged ("Based on data from NEVO online version 2025/9.0,
--     RIVM, Bilthoven"): generated by scripts/import-nevo.mjs from NEVO's own
--     file, set by NEVO code, rewritten only where they differ.
--  3. A supplement can count towards vitamins and minerals (SUP-07): what
--     one dose gives, in the same codes and units, on the supplement's own
--     row ('nutrients'). On the row rather than in each day's tick: a dose
--     is the same every day, the tick stays a plain yes or no, and an edit
--     syncs field by field like the rest of the supplement.
--  4. A photo per recipe (REC-11): the recipe keeps the name of its photo
--     ('photo_path'), which lives in the private 'record-photos' bucket of
--     033 under 'recipes/<recipe id>/<photo id>.jpg'. Who may see it is
--     exactly who may read the recipe (its owner; everyone for an approved
--     shared recipe; the reviewer for a proposed one): the policy asks the
--     recipe table, under the caller's own row-level security. Only the
--     recipe's owner may add, replace or remove it. There is no household
--     sharing of recipes (019: private, proposed, public), so no household
--     rule is needed; if one is added to recipe_read, photos follow it.
--     A new photo on an approved recipe is a change to it, so it goes back
--     for review like any other (019's guard).
--
-- Safe to run more than once. The Storage part runs only where Supabase
-- Storage is present (a plain Postgres stand-in skips it with a notice).

-- 1: vitamins and minerals on a food ---------------------------------------------------
-- Whether a micros object is one the app can read: an object whose keys are
-- the known codes and whose values are numbers from 0 to 1,000,000.
create or replace function private.micros_ok(m jsonb)
returns boolean language sql immutable set search_path = '' as $$
  select m is null or (
    jsonb_typeof(m) = 'object'
    and (select coalesce(bool_and(
           key = any (array['va','vd','ve','vk','vc','b1','b2','b3','b6','b9','b12','b7','b5',
                            'k','cl','ca','p','mg','fe','zn','cu','mn','f','se','cr','mo','i'])
           and jsonb_typeof(value) = 'number'
           and (value::text)::numeric between 0 and 1000000), true)
         from jsonb_each(m)))
$$;
revoke all on function private.micros_ok(jsonb) from public, anon;
grant execute on function private.micros_ok(jsonb) to authenticated;

alter table public.food add column if not exists micros jsonb;
do $$ begin
  alter table public.food add constraint food_micros_check check (private.micros_ok(micros));
exception when duplicate_object then null; end $$;

-- 3: what a supplement's dose gives --------------------------------------------------------
alter table public.supplement add column if not exists nutrients jsonb;
do $$ begin
  alter table public.supplement add constraint supplement_nutrients_check check (private.micros_ok(nutrients));
exception when duplicate_object then null; end $$;

-- 4: a recipe's photo ------------------------------------------------------------------------
alter table public.recipe add column if not exists photo_path text;
do $$ begin
  alter table public.recipe add constraint recipe_photo_check check (
    photo_path is null or photo_path ~ ('^recipes/' || id::text || '/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.jpg$'));
exception when duplicate_object then null; end $$;

-- The recipe a photo belongs to: the second folder of 'recipes/<id>/<photo>.jpg'.
-- Anything else belongs to no recipe, so no policy below can match it.
create or replace function private.photo_recipe(object_name text)
returns uuid language sql immutable set search_path = '' as $$
  select case when split_part(object_name, '/', 1) = 'recipes'
              and split_part(object_name, '/', 2) ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              and split_part(object_name, '/', 3) ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.jpg$'
              and split_part(object_name, '/', 4) = ''
         then split_part(object_name, '/', 2)::uuid end
$$;
revoke all on function private.photo_recipe(text) from public, anon;
grant execute on function private.photo_recipe(text) to authenticated;

-- The caller's own recipes: security definer, so the answer does not depend
-- on which recipes the caller can read, only on which they own.
create or replace function private.my_recipes()
returns setof uuid language sql stable security definer set search_path = '' as $$
  select id from public.recipe where owner_id = (select auth.uid())
$$;
revoke all on function private.my_recipes() from public, anon;
grant execute on function private.my_recipes() to authenticated;

do $$
begin
  if to_regclass('storage.buckets') is null or to_regclass('storage.objects') is null then
    raise notice '036: no Storage here; the recipe photo policies are left for the live project';
    return;
  end if;

  -- The bucket is 033's; made here too, the same, in case 033's Storage part
  -- was skipped where Storage arrived later.
  execute $q$
    insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
    values ('record-photos', 'record-photos', false, 2097152, array['image/jpeg'])
    on conflict (id) do update set public = false, file_size_limit = 2097152, allowed_mime_types = array['image/jpeg']
  $q$;

  execute 'drop policy if exists recipe_photos_read on storage.objects';
  execute 'drop policy if exists recipe_photos_insert on storage.objects';
  execute 'drop policy if exists recipe_photos_update on storage.objects';
  execute 'drop policy if exists recipe_photos_delete on storage.objects';

  -- Readable exactly when the recipe is: the subquery runs under the
  -- caller's own row-level security on recipe (019's recipe_read).
  execute $q$
    create policy recipe_photos_read on storage.objects for select to authenticated
      using (bucket_id = 'record-photos' and private.photo_recipe(name) in (select id from public.recipe))
  $q$;
  execute $q$
    create policy recipe_photos_insert on storage.objects for insert to authenticated
      with check (bucket_id = 'record-photos' and private.photo_recipe(name) in (select private.my_recipes()))
  $q$;
  execute $q$
    create policy recipe_photos_update on storage.objects for update to authenticated
      using (bucket_id = 'record-photos' and private.photo_recipe(name) in (select private.my_recipes()))
      with check (bucket_id = 'record-photos' and private.photo_recipe(name) in (select private.my_recipes()))
  $q$;
  execute $q$
    create policy recipe_photos_delete on storage.objects for delete to authenticated
      using (bucket_id = 'record-photos' and private.photo_recipe(name) in (select private.my_recipes()))
  $q$;
end $$;

